/bin/zsh -lc "python3 -B - <<'PY'
import sqlite3
con = sqlite3.connect(':memory:')
con.executescript('''
CREATE TABLE records (tenant TEXT, name TEXT, value INTEGER, PRIMARY KEY (tenant,name));
CREATE TABLE events (kind TEXT);
INSERT INTO records VALUES ('one','a',1), ('two','b',2);
CREATE TRIGGER benign AFTER UPDATE ON records BEGIN
  UPDATE records SET value=value WHERE tenant=NEW.tenant AND name=NEW.name;
END;
CREATE TRIGGER main_ignore AFTER UPDATE ON records BEGIN SELECT RAISE(IGNORE); END;
CREATE TEMP TRIGGER observe_update AFTER UPDATE ON main.records BEGIN
  INSERT INTO events VALUES ('update');
END;
CREATE TEMP TRIGGER observe_delete AFTER DELETE ON main.records BEGIN
  INSERT INTO events VALUES ('delete');
END;
''')
print('SQLite:', sqlite3.sqlite_version)
print('Default recursive triggers:', con.execute('PRAGMA recursive_triggers').fetchone()[0])
con.execute(\"UPDATE records SET value=3 WHERE tenant='one'\")
print('TEMP observer fires before persistent AFTER IGNORE:', con.execute('SELECT count(*) FROM events').fetchone()[0] > 0)
con.execute('DELETE FROM events')
con.execute(\"UPDATE OR REPLACE records SET rowid=2 WHERE tenant='one'\")
print('Replacement row count:', con.execute('SELECT count(*) FROM records').fetchone()[0])
print('Implicit replacement delete events:', con.execute(\"SELECT count(*) FROM events WHERE kind='delete'\").fetchone()[0])
PY"

